        "caption": "Chân dung Nguyễn Ái Quốc (năm 1920 tại Pháp) — Tác giả truyện ngắn trào phúng \"Những trò lố hay là Va-ren và Phan Bội Châu\".",
        "authorImage": "img/authors/nguyen_ai_quoc.jpg"
