      "context": "Ra đời ngay trước khi Va-ren đặt chân sang Đông Dương, nhằm mục đích cổ vũ phong trào đòi ân xá cụ Phan Bội Châu của nhân dân cả nước sau khi cụ bị mật thám Pháp bắt cóc tại Thượng Hải tháng 6/1925.",
      "authorAesthetics": "Nguyễn Ái Quốc sử dụng văn chương như một thứ vũ khí chiến đấu sắc bén, kết hợp bút pháp châm biếm sâu cay, trí tưởng tượng hư cấu tài tình và nghệ thuật tương phản triệt để để lột trần bộ mặt đạo đức giả của chủ nghĩa thực dân.",
