          "content": "\"Thế sự du du nại lão hà / Vô cùng thiên địa nhập hàm ca\" (Việc đời dằng dặc mà ta đã già rồi biết làm sao / Đất trời vô tận thu cả vào trong khúc hát say). Người tráng sĩ đứng trước không gian vô cùng của đất trời và thời gian vô tận của thế sự mà ý thức sâu sắc về sự hữu hạn của đời người. Khúc hát say không phải là sự trốn tránh yếm thế mà là tiếng thở dài u uất của bậc hào kiệt trước vận nước gian truân.",
