          "Vũ Trọng Phụng là ngọn cờ đầu của trào lưu văn học hiện thực phê phán Việt Nam 1930–1945, người được mệnh danh là \"ông vua phóng sự đất Bắc\". Kiệt tác tiểu thuyết trào phúng \"Số đỏ\" (1936) là đỉnh cao nghệ thuật châm biếm đanh thép của ông. Trong đó, đoạn trích \"Xuân Tóc Đỏ cứu quốc\" đã tái hiện một màn hài kịch chính trị đỉnh điểm, vạch trần bộ mặt đạo đức giả của chế độ thực dân và thói a dua mù quáng của xã hội thượng lưu thời thuộc địa.",
